h={'Authorization':'Basic '+base64.b64encode(('ditto:'+os.environ['DITTO_PASSWORD']).encode()).decode()}
for n in ['coordinator','future-result','energy']:
 d=json.load(urllib.request.urlopen(urllib.request.Request('http://127.0.0.1:'+os.environ['DITTO_PORT']+'/api/2/things/kz.tynys:'+n,headers=h)))
 f={k:v.get('properties',{}).get('value') for k,v in d['features'].items()}
 if n=='coordinator': print(n,{k:v for k,v in f.items() if not k.endswith('json')},'plan',str(f.get('plan_json'))[:900])
 if n=='future-result':
  r=json.loads(f['result_json']);print(n,'status',f.get('status'),'summary',json.dumps(r.get('summary'),ensure_ascii=False)[:2200])
 if n=='energy': print(n,'sizing rows',len(d['attributes'].get('sizing',[])),'equivalent',d['attributes'].get('wind_equivalent'))
PY

